style.css:
@-moz-document domain("chat.openai.com") {
/* Base font: handwriting style */
  body, * {
    font-family: "Comic Neue", "Patrick Hand", "Caveat", cursive !important;
  }

  /* GENERAL BACKGROUNDS: swapped to lighter button blue */
  body, html, main, section, article, aside, header, footer, nav, div, span {
    background-color: #cce7ff !important; /* lighter blue */
    color: #001f4d !important; /* darkest blue text */
  }

  /* TEXT ELEMENTS */
  h1, h2, h3, h4, h5, h6, p, li, span, strong, em {
    color: #001f4d !important; /* darkest blue */
    background-color: transparent !important;
  }

  /* LINKS */
  a, a:visited {
    color: #001f4d !important;
    text-decoration: underline dotted #001f4d !important;
  }
  a:hover {
    color: #004080 !important;
    background-color: #f0faff !important;
  }

  /* BUTTONS + ACTION ELEMENTS: swapped to lightest blue */
  button, .btn, input[type="submit"], input[type="button"], input[type="reset"], .option, .action {
    background-color: #f0faff !important; /* lightest blue */
    color: #001f4d !important;
    border: 2px solid #a3d4ff !important;
    border-radius: 12px !important;
    padding: 8px 16px !important;
    font-weight: bold !important;
    transition: all 0.2s ease-in-out !important;
  }
  button:hover, .btn:hover, .option:hover, .action:hover {
    background-color: #e0f5ff !important;
    color: #001f4d !important;
    transform: scale(1.05) !important;
  }

  /* INPUTS + TEXTAREAS */
  input, textarea, select {
    background-color: #f0faff !important;
    color: #001f4d !important;
    border: 1px solid #cce7ff !important;
    border-radius: 10px !important;
    padding: 6px 10px !important;
  }
  input:focus, textarea:focus, select:focus {
    outline: none !important;
    border-color: #a3d4ff !important;
    box-shadow: 0 0 8px #cce7ff !important;
  }

  /* CARDS / BOXES */
  .card, .box, .panel, .container, .modal, .popup {
    background-color: #cce7ff !important;
    border: 1px solid #a3d4ff !important;
    border-radius: 14px !important;
    color: #001f4d !important;
    padding: 12px !important;
    box-shadow: 0 4px 10px rgba(173, 216, 230, 0.5) !important;
  }

  /* TABLES */
  table {
    border-collapse: collapse !important;
    width: 100% !important;
    background-color: #cce7ff !important;
    color: #001f4d !important;
  }
  th, td {
    border: 1px solid #a3d4ff !important;
    padding: 8px !important;
  }
  th {
    background-color: #f0faff !important;
    color: #001f4d !important;
  }

  /* SCROLLBARS */
  ::-webkit-scrollbar {
    width: 12px !important;
  }
  ::-webkit-scrollbar-track {
    background: #cce7ff !important;
  }
  ::-webkit-scrollbar-thumb {
    background-color: #f0faff !important;
    border-radius: 10px !important;
    border: 2px solid #cce7ff !important;
  }
  ::-webkit-scrollbar-thumb:hover {
    background-color: #e0f5ff !important;
  }

  /* FORMS + DROPDOWNS */
  select, option {
    background-color: #f0faff !important;
    color: #001f4d !important;
    border: 1px solid #cce7ff !important;
  }

  /* HOVER STATES */
  *:hover {
    transition: background-color 0.3s ease, color 0.3s ease !important;
  }

  /* EXTRA POLISH: notifications, alerts */
  .alert, .notification {
    background-color: #f0faff !important;
    color: #001f4d !important;
    border-left: 6px solid #a3d4ff !important;
    padding: 10px !important;
  }

  /* FINISHING TOUCHES */
  hr {
    border: 0 !important;
    border-top: 1px solid #a3d4ff !important;
  }
}
